// Parses LinkedIn job alert emails (plain-text part) into clean job rows.
// Tracking parameters and login tokens are removed from every link.
const HEADER = /^(your job alert for|\d+\+? new jobs? match|new jobs? match|jobs you may be interested in)/i;

const jobs = [];

for (const item of $input.all()) {
  const text = item.json.textPlain || item.json.text || '';
  const chunks = text.split(/\n\s*-{10,}\s*\n/);

  for (const chunk of chunks) {
    const m = chunk.match(/View job:\s*(\S+)/i);
    if (!m) continue;
    const idMatch = m[1].match(/jobs\/view\/(\d+)/);
    if (!idMatch) continue;
    const jobId = idMatch[1];

    const lines = chunk
      .slice(0, m.index)
      .split('\n')
      .map(l => l.trim())
      .filter(l => l && !HEADER.test(l));

    if (lines.length < 3) continue;
    const [title, company, rawLocation] = lines;

    let work_mode = 'unknown';
    if (/remote/i.test(rawLocation)) work_mode = 'remote';
    else if (/hybrid|h[ií]brido/i.test(rawLocation)) work_mode = 'hybrid';
    else if (/on-?site|presencial/i.test(rawLocation)) work_mode = 'onsite';

    const location = rawLocation.replace(/\s*\((remote|hybrid|on-?site|remoto|h[ií]brido|presencial)\)\s*/i, '').trim();

    jobs.push({
      external_id: jobId,
      title,
      company,
      location,
      work_mode,
      url: `https://www.linkedin.com/jobs/view/${jobId}/`,
      description: null,
      posted_at: item.json.date ? new Date(item.json.date).toISOString() : null,
      publisher: 'LinkedIn',
      salary_min: null,
      salary_max: null,
      salary_currency: null,
      salary_period: null,
    });
  }
}

return [{ json: { jobs, fetched: jobs.length } }];
